from html import escape
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT))
CSS='\n:root{color-scheme:light;--ink:#1d1d1f;--muted:#6e6e73;--blue:#007aff}\n*{box-sizing:border-box}body{margin:0;background:#f5f5f7;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",system-ui,sans-serif;line-height:1.75}\nmain{max-width:960px;margin:auto;padding:40px 22px 80px}header{padding:10px 6px 30px}h1{font-size:clamp(28px,5vw,42px);line-height:1.25;letter-spacing:-.04em;margin:8px 0 12px}h2{font-size:21px;letter-spacing:-.015em;margin:0 0 20px}.eyebrow{font-size:12px;letter-spacing:.15em;color:var(--blue);font-weight:650}.muted,.small{color:var(--muted);font-size:13px}.card{background:#fff;border:1px solid #e8e8ed;border-radius:12px;box-shadow:0 1px 3px rgba(0,0,0,.06);padding:28px;margin-bottom:20px}.hero{font-size:24px;line-height:1.65;margin-top:0}p{margin:12px 0}.tag{display:inline-block;padding:5px 10px;background:#edf5ff;color:#145b9b;border-radius:6px;font-size:12px;margin:8px 8px 0 0}.diagram{overflow-x:auto}.diagram svg{display:block;max-width:100%;height:auto;margin:8px auto 24px}.pending{padding:20px;border:1px dashed #c58c33;border-radius:8px;background:#fffaf0;color:#725320;font-size:14px;margin:12px 0 22px}.pending strong{font-size:12px;letter-spacing:.06em}.pending p{margin:6px 0}dl{margin:18px 0}dt{font-weight:650;color:#15599c;margin-top:18px}dd{margin:5px 0 0}.sample{background:#f5f5f7;padding:18px;border-radius:8px}code{font:13px "SFMono-Regular",Consolas,monospace;background:#f5f5f7;padding:3px 6px;border-radius:4px}li{margin:7px 0}.comment{border-top:1px solid #ececf0;margin-top:24px;padding-top:18px}label{display:block;font-size:13px;color:var(--muted);margin-bottom:8px}label span{margin-left:12px;color:#237343}textarea{width:100%;min-height:76px;resize:vertical;border:1px solid #d2d2d7;border-radius:8px;padding:12px;font:inherit;font-size:14px;background:#fcfcfd}textarea:focus{outline:2px solid #7ab7ff;outline-offset:2px}button{background:var(--blue);color:#fff;border:0;border-radius:7px;padding:10px 16px;font:inherit;font-size:14px;cursor:pointer;margin:14px 12px 0 0}.secondary{background:#eaf3ff;color:#15599c}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.7 system-ui,sans-serif;background:#f5f5f7;padding:16px;border-radius:8px}.chunk{margin-top:18px}#copy-status{font-size:13px;color:var(--muted)}a{color:#0067d6;text-decoration:none}@media(max-width:600px){main{padding:22px 12px 50px}.card{padding:22px 18px;border-radius:12px}.hero{font-size:21px}h2{font-size:18px}}\n'
SCRIPT='\n(() => {\n  \'use strict\';\n  const marker = \'【页面意见汇总】FLY-2900\';\n  const prefix = \'flywheel:design-comments:\' + location.pathname + \':\';\n  const inputs = Array.from(document.querySelectorAll(\'textarea[data-comment]\'));\n  const chunksBox = document.getElementById(\'comment-chunks\');\n  const status = document.getElementById(\'copy-status\');\n  let chunks = [];\n  function splitText(text) {\n    const chars = Array.from(text);\n    const room = 1800 - Array.from(marker).length - 1;\n    if (!chars.length) return [marker + \'\\n（暂无意见）\'];\n    const result = [];\n    let part = \'\';\n    for (const char of chars) {\n      if (part.length + char.length > room) {\n        result.push(marker + \'\\n\' + part);\n        part = \'\';\n      }\n      part += char;\n    }\n    if (part) result.push(marker + \'\\n\' + part);\n    return result;\n  }\n  function fallbackCopy(text) {\n    const helper = document.createElement(\'textarea\');\n    helper.value = text;\n    helper.setAttribute(\'aria-label\', \'复制意见\');\n    helper.style.position = \'fixed\';\n    helper.style.left = \'-10000px\';\n    document.body.appendChild(helper);\n    helper.select();\n    let ok = false;\n    try { ok = document.execCommand(\'copy\'); } catch (_) { ok = false; }\n    helper.remove();\n    return ok;\n  }\n  async function copyText(text) {\n    let ok = false;\n    if (navigator.clipboard && typeof navigator.clipboard.writeText === \'function\') {\n      try { await navigator.clipboard.writeText(text); ok = true; }\n      catch (_) { ok = fallbackCopy(text); }\n    } else { ok = fallbackCopy(text); }\n    status.textContent = ok ? \'已复制\' : \'复制失败，请选中下方文字手动复制\';\n  }\n  function updateSummary() {\n    const entries = inputs.filter(input => input.value.trim()).map(input =>\n      input.dataset.title + \'\\n\' + input.value.trim());\n    chunks = splitText(entries.join(\'\\n\\n\'));\n    chunksBox.replaceChildren();\n    chunks.forEach((chunk, index) => {\n      const block = document.createElement(\'div\');\n      block.className = \'chunk\';\n      const text = document.createElement(\'pre\');\n      text.textContent = chunk;\n      const button = document.createElement(\'button\');\n      button.type = \'button\';\n      button.className = \'secondary\';\n      button.textContent = \'复制第 \' + (index + 1) + \' 段\';\n      button.addEventListener(\'click\', () => copyText(chunk));\n      block.appendChild(text);\n      block.appendChild(button);\n      chunksBox.appendChild(block);\n    });\n  }\n  inputs.forEach(input => {\n    const saved = document.querySelector(\'[data-saved="\' + input.dataset.comment + \'"]\');\n    try { input.value = localStorage.getItem(prefix + input.dataset.comment) || \'\'; }\n    catch (_) { if (saved) saved.textContent = \'无法读取本机保存\'; }\n    input.addEventListener(\'input\', () => {\n      try {\n        localStorage.setItem(prefix + input.dataset.comment, input.value);\n        if (saved) saved.textContent = \'已保存\';\n      } catch (_) { if (saved) saved.textContent = \'未保存；仍可复制\'; }\n      updateSummary();\n    });\n  });\n  document.getElementById(\'copy-all\').addEventListener(\'click\', () => copyText(chunks.join(\'\\n\\n\')));\n  updateSummary();\n})();\n'

import re
from sections import TITLE, EYEBROW, H1, SUB, DIAGRAMS, SECTIONS

def shrink(svg):
    # Round long float coordinates to keep the page small (stateDiagram bloat).
    return re.sub(r'(\d+\.\d{2})\d+', r'\1', svg)
def diagram(name):
    path=ROOT/(name+'.svg')
    if path.exists():
        return '<div class="diagram">'+shrink(path.read_text())+'</div>'
    return '<div class="pending" role="note"><strong>DIAGRAM PENDING LOCAL RENDER</strong><p>本地渲染失败，Mermaid 源文件 '+escape(name)+'.mmd 保留在同目录。</p></div>'
def comment(key,title):
    return '<div class="comment"><label for="comment-'+escape(key)+'">这一节的意见<span data-saved="'+escape(key)+'" aria-live="polite"></span></label><textarea id="comment-'+escape(key)+'" data-comment="'+escape(key)+'" data-title="'+escape(title)+'" placeholder="自动保存在当前浏览器；复制给组长才会送出"></textarea></div>'
cards=[]
for key,title,body in SECTIONS:
    for name in DIAGRAMS:
        body=body.replace('{{'+name+'}}',diagram(name))
    cards.append('<section class="card" id="'+escape(key)+'"><h2>'+escape(title)+'</h2>'+body+comment(key,title)+'</section>')
n=len(SECTIONS)+1
cards.append('<section class="card" id="feedback"><h2>'+str(n).zfill(2)+' / 意见汇总</h2><p>每节留言实时汇总，长意见分段复制。这些是修改意见，不是通过信号；不会自动送出。</p>'+comment('feedback',str(n).zfill(2)+' / 总体意见')+'<button type="button" id="copy-all">复制全部意见</button><span id="copy-status" role="status"></span><div id="comment-chunks"></div></section>')
html='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(TITLE)+'</title><style>'+CSS+'</style></head><body><main><header><div class="eyebrow">'+escape(EYEBROW)+'</div><h1>'+escape(H1)+'</h1><p class="muted">'+escape(SUB)+'</p></header>'+''.join(cards)+'<script nonce="__CSP_NONCE__">'+SCRIPT+'</script></main></body></html>'
(ROOT/'founder-design.html').write_text(html)
print('Built founder-design.html:',len(html.encode()),'bytes')
